(196339, '_transient_ctf__NIck_Alvarez673', '[{\"user\":{\"name\":\"Nick Alvarez\",\"description\":\"Managing Director & National Practice Leader, @alvarezmarsal Private Equity Performance Improvement; Loves good wine, golf & @SoulCycle; Posts are my own views.\",\"statuses_count\":1405,\"followers_count\":323,\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Moments like this! So thankful to be part of such a great team. #PrivateEquity #PerformanceImprovement #LikeWhatYouDo #LikeWhoYouDoItWith \",\"id_str\":\"1191777957687238656\",\"created_at\":\"Tue Nov 05 18:03:01 +0000 2019\",\"retweet_count\":0,\"favorite_count\":5,\"extended_entities\":{\"media\":[{\"media_url_https\":\"https:\\/\\/pbs.twimg.com\\/media\\/EIoLu_WW4AAz-lF.jpg\",\"type\":\"photo\",\"sizes\":{\"thumb\":{\"w\":150,\"h\":150,\"resize\":\"crop\"},\"large\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"medium\":{\"w\":1024,\"h\":512,\"resize\":\"fit\"},\"small\":{\"w\":680,\"h\":340,\"resize\":\"fit\"}}}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Helping your team find purpose in their work starts with modeling the proper behavior. @HarvardBiz: https:\\/\\/t.co\\/yJg8R0BsQL #Leadership #BusinessLeadership #TeamCulture #Authenticity\",\"id_str\":\"1191475962594123777\",\"created_at\":\"Mon Nov 04 22:03:00 +0000 2019\",\"retweet_count\":0,\"favorite_count\":5,\"entities\":{\"urls\":[{\"expanded_url\":\"http:\\/\\/bit.ly\\/2Wk28Fv\"}]}},{\"user\":{\"name\":\"Nick Alvarez\",\"screen_name\":\"NIck_Alvarez67\",\"verified\":false,\"profile_image_url_https\":\"https:\\/\\/pbs.twimg.com\\/profile_images\\/1068226268670427137\\/Yj31hhlV_normal.jpg\",\"utc_offset\":null},\"text\":\"Progressive #procurement will positively affect companies, climate change, and wages of individual employees, if governments were to get on board. @openDemocracy: https:\\/\\/t.co\\/QbwcMNQDZP  #OperationalImprovement @bengglover @Rose_Lasko\",\"id_str\":\"1191451809358974976\",\"created_at\":\"Mon Nov 04 20:27:02 +0000 2019\",\"retweet_count\":1,\"favorite_count\":5,\"entities\":{\"urls\":[{\"expanded_url\":\"http:\\/\\/bit.ly\\/34b2VeW\"}]}}]', 'no'),
