(4645, 640, '_header-image', 'field_58911460d81fb'),
(4646, 640, 'header-title', 'Icici Bank Registers the First Case Under the Bankruptcy Code'),
(4647, 640, '_header-title', 'field_5891147bd81fc'),
(4648, 640, 'header-sub-title', ''),
