(36339, 1742, 'css', 'strong {\r\n    text-transform: uppercase;\r\n}\r\n#section-eoy-title {\r\n    width: 100%;\r\n    -webkit-background-size: cover;\r\n    -moz-background-size: cover;\r\n    -o-background-size: cover;\r\n    background-size: cover;\r\n    background-attachment: scroll;\r\n height: auto;\r\n    margin: 15px 0px 15px 0px;\r\n    display: inline-block;\r\n    color: #fff;\r\n    font-family: \'Helvetica Neue LT W01_65 Md\';\r\n    padding: 10px;\r\n    font-size: 26px;\r\n    text-transform: uppercase;\r\n}\r\n\r\n.eoy-title1 {\r\n    background: url(\"https://www.am-globaltag.com/wp-content/uploads/2018/01/man-title1-2.jpg\") center top no-repeat;\r\n        background-attachment: scroll;\r\n        background-size: auto auto;\r\n}\r\n.tl-p ul li {\r\n    list-style: disc;\r\n}\r\n.news-src {\r\ndisplay: none;\r\n}\r\n\r\n@media only screen\r\nand (min-width : 320px)\r\nand (max-width : 480px) {\r\n#section-eoy-title {\r\n   padding: 12px;\r\nfont-size: 15px;\r\nline-height: 18px;\r\n}\r\n.m-fix {\r\npadding: 20px !important;\r\n}\r\n.m-fix2 {\r\nwidth: 30% !important;\r\n}\r\n}\r\n'),
